sp_widget.client_script:
function($scope, $rootScope, $timeout) {
    var chartInstanceLinha = null;

    $scope.anoSelecionado = "";
    $scope.mesSelecionado = "";

    function carregarDadosDoServer() {
        var filtros = {
            ano: $scope.anoSelecionado || "",
            mes: ""
        };

        if ($scope.mesSelecionado) {
            // Garante zero à esquerda no mês
            var mesNum = parseInt($scope.mesSelecionado, 10);
            filtros.mes = ("0" + mesNum).slice(-2);  // Ex: '1' => '01'
        }

        $scope.server.get(filtros).then(function(response) {
            var listaDados = response.data.dadosGraficoRCL || [];
            inicializarGraficoLinha(listaDados);
        });
    }

    $rootScope.$on('anoSelecionado', function(event, ano) {
        $scope.anoSelecionado = ano;
        carregarDadosDoServer();
    });

    $rootScope.$on('mesSelecionado', function(event, mes) {
        $scope.mesSelecionado = mes;
        carregarDadosDoServer();
    });

    carregarDadosDoServer();

    function inicializarGraficoLinha(listaDados) {
        if (!listaDados || listaDados.length === 0) {
            if (chartInstanceLinha) {
                chartInstanceLinha.destroy();
                chartInstanceLinha = null;
            }
            $scope.exibirGraficoLinha = false;
            $scope.$applyAsync();
            return;
        }

        $scope.exibirGraficoLinha = true;
        $scope.$applyAsync();

        var mesesLabels = [
            'Janeiro', 'Fevereiro', 'Março', 'Abril', 'Maio', 'Junho',
            'Julho', 'Agosto', 'Setembro', 'Outubro', 'Novembro', 'Dezembro'
        ];

        // Mapeia os meses numéricos para índices
        var mesesMap = {
            "01": 0, "02": 1, "03": 2, "04": 3, "05": 4, "06": 5,
            "07": 6, "08": 7, "09": 8, "10": 9, "11": 10, "12": 11
        };

        var anos = [];
        for (var i = 0; i < listaDados.length; i++) {
            var ano = listaDados[i].ano;
            if (anos.indexOf(ano) === -1) anos.push(ano);
        }
        anos.sort();
        var anoMaisRecente = anos.length > 0 ? anos[anos.length - 1] : null;
        var anoAnterior = anos.length > 1 ? anos[anos.length - 2] : null;

        var dadosAnoMaisRecente = new Array(12).fill(0);
        var dadosAnoAnterior = new Array(12).fill(0);

        for (var j = 0; j < listaDados.length; j++) {
            var item = listaDados[j];
            var mesIndex = mesesMap[item.mes];
            if (mesIndex === undefined) continue;

            if (item.ano === anoMaisRecente) {
                dadosAnoMaisRecente[mesIndex] += item.valorRCL / 1;
            } else if (item.ano === anoAnterior) {
                dadosAnoAnterior[mesIndex] += item.valorRCL / 1;
            }
        }

        var contexto = document.getElementById('graficoLimitePessoalLinha').getContext('2d');

        if (chartInstanceLinha) {
            chartInstanceLinha.destroy();
        }

        var datasets = [];

        if (anoAnterior !== null) {
            datasets.push({
                label: 'Série: RCL ' + anoAnterior,
                data: dadosAnoAnterior,
                borderColor: '#6BB7F0',
                backgroundColor: 'rgba(107, 183, 240, 1)',
                fill: false,
                tension: 0.3,
                pointRadius: 6,
                pointHoverRadius: 8,
                pointBackgroundColor: '#6BB7F0',
                pointBorderColor: '#6BB7F0',
                pointStyle: 'rect'
            });
        }

        datasets.push({
            label: 'Série: RCL ' + anoMaisRecente,
            data: dadosAnoMaisRecente,
            borderColor: '#4A75B1',
            backgroundColor: 'rgba(74, 117, 177, 1)',
            fill: false,
            tension: 0.3,
            pointRadius: 6,
            pointHoverRadius: 8,
            pointBackgroundColor: '#4A75B1',
            pointBorderColor: '#4A75B1'
        });

        chartInstanceLinha = new Chart(contexto, {
            type: 'bar',
            data: {
                labels: mesesLabels,
                datasets: datasets
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                scales: {
                    x: { title: { display: true, text: 'Mês' } },
                    y: {
                        beginAtZero: true,
                        title: { display: true, text: 'Valor em R$' },
                        ticks: {
                            callback: function(value) {
                                return 'R$ ' + value.toLocaleString('pt-BR') + '';
                            }
                        }
                    }
                },
                plugins: {
                    legend: { position: 'top' },
                    tooltip: {
                        callbacks: {
                            label: function(context) {
                                return context.dataset.label + ': R$ ' + context.parsed.y.toLocaleString('pt-BR') + '';
                            }
                        }
                    }
                }
            }
        });
    }
}

sp_widget.css:
canvas {
  display: block;
  margin: 0 auto;
}

h3, div {
 font-family: 'Roboto Flex', sans-serif;
}

/* --- Media Queries para Responsividade --- */

/* Telas Pequenas (Mobile S, M, L - até 767px) */
@media (max-width: 767px) {
  canvas {
    max-width: 90%; /* Ajustar a largura máxima do canvas */
  }
  h3 {
    font-size: 1rem; /* Ajustar o tamanho da fonte do título */
  }
}

/* Tablets (iPad Mini, iPad Air, Surface Duo, Galaxy Z Fold 5 - 768px até 1023px) */
@media (min-width: 768px) and (max-width: 1023px) {
  canvas {
    max-width: 80%;
  }
  h3 {
    font-size: 1.1rem;
  }
}

/* Laptops e Telas Maiores (iPad Pro, Surface Pro 7, Laptops, 4K - 1024px em diante) */
@media (min-width: 1024px) {
  canvas {
    max-width: none;
  }
  h3 {
  }
}

/* Ajustes para o Surface Duo (540x720) */
@media (width: 540px) and (height: 720px) {
    canvas {
        max-width: 95%;
    }
}

/* Ajustes para Galaxy Z Fold 5 (max-width: 350px) */
@media (max-width: 350px) {
    h3 {
        font-size: 0.9rem;
    }
}

sp_widget.script:
(function() {
    input = input || {};

    var anoFiltro = input.ano || "";
    var mesFiltro = input.mes || "";

    var gr = new GlideRecord('x_sded9_portal_t_0_u_rreo');

    if (anoFiltro !== "") {
        var anoSelecionado = parseInt(anoFiltro, 10);

        // Buscar anos disponíveis na tabela para saber se existe ano anterior
        var anosDisponiveis = [];
        var grAnos = new GlideRecord('x_sded9_portal_t_0_u_rreo');
        grAnos.orderByDesc('u_ano');
        grAnos.query();
        while (grAnos.next()) {
            var anoAtual = parseInt(grAnos.getValue('u_ano'), 10);
            if (anosDisponiveis.indexOf(anoAtual) === -1) {
                anosDisponiveis.push(anoAtual);
            }
        }
        anosDisponiveis.sort();

        var anoAnterior = null;
        var indexSelecionado = anosDisponiveis.indexOf(anoSelecionado);
        if (indexSelecionado > 0) {
            anoAnterior = anosDisponiveis[indexSelecionado - 1];
        }

        // Criar query para ano selecionado OU ano anterior (se existir)
        if (anoAnterior !== null) {
            var qc = gr.addQuery('u_ano', anoSelecionado);
            qc.addOrCondition('u_ano', anoAnterior);
        } else {
            gr.addQuery('u_ano', anoSelecionado);
        }
    }

    if (mesFiltro !== "") {
        gr.addQuery('u_mes', mesFiltro);
    }

    gr.orderByDesc('u_ano');
    gr.orderBy('u_mes');
    gr.query();

    var listaDados = [];
    while (gr.next()) {
        listaDados.push({
            ano: parseInt(gr.getValue('u_ano'), 10),
            mes: gr.getValue('u_mes'),
            valorRCL: parseFloat(gr.getValue('adjusted_rreo_fiscal_management_report_2')) || 0
        });
    }

    data.dadosGraficoRCL = listaDados;
})();
